    private const LANGUAGES = ['en'=>'EN','fr'=>'FR','es'=>'ES','ru'=>'RU','tr'=>'TR','ar'=>'AR','he'=>'HE'];

    public function index(?string $locale = 'en')
    {
        $locale = array_key_exists($locale, self::LANGUAGES) ? $locale : 'en';
        $guide = $this->guides()[$locale];
        $icons = ['users','gamepad','tree','trophy','credit-card','dice','magic','chart-line','chart-line','user-friends','gem','cogs','store','user-shield'];
        foreach ($guide['sections'] as $index => &$section) $section['icon'] = $icons[$index];

        return view('liteback.help.index', [
            'locale' => $locale,
            'languages' => self::LANGUAGES,
            'guide' => $guide,
            'rtl' => in_array($locale, ['ar', 'he'], true),
        ]);
    }

