            'ar' => ['title'=>'مساعدة Liteback','intro'=>'دليل مختصر لوحدة تحكم المشغّل. أكّد التغييرات المهمة قبل الحفظ؛ فبعض الإجراءات تؤثر في الظهور أو الأرصدة أو الخدمات النشطة.', 'sections'=>[
                ['title'=>'المستخدمون','body'=>'ابحث عن حسابات اللاعبين وراجع حالتها ووثّق أي تعديل للرصيد. افتح التفاصيل قبل تغيير بيانات لاعب.'],['title'=>'الألعاب','body'=>'أدر الكتالوج والظهور والموفّرين وإعدادات التسليم. عطّل عنواناً لإخفائه من دون حذف السجل.'],['title'=>'CEDAR','body'=>'أدر كتالوج CEDAR المحمي بشكل منفصل. زامن التحديثات المصرّح بها فقط، وحافظ على المعرّفات والجولات السابقة.'],['title'=>'المراهنات الرياضية','body'=>'استخدم اللوحة والفئات والأحداث والتسويات والإعدادات للتحكم في قسم الرياضة. لا تسوِّ أو تردّ رهاناً قبل التحقق من النتيجة المصدرية.'],['title'=>'المدفوعات والسحوبات','body'=>'راجع الإيداعات اليدوية وطلبات السحب قبل الموافقة. لا تُدخل الأسرار مطلقاً في الملاحظات أو الحقول العامة.'],['title'=>'منطقة لوتو والجاكبوت','body'=>'أنشئ أو فعّل ألعاب السحب واضبط أعمدة النتيجة وشغّل سحباً محدداً فقط عندما يكون جاهزاً. تسجَّل النتائج للتدقيق.'],['title'=>'أسواق التوقعات','body'=>'أنشئ الأسواق وراجعها هنا. التسوية إجراء مهم: تحقّق من النتيجة النهائية واتبع العملية الموثقة.'],['title'=>'تداول العملات الرقمية','body'=>'حدّث قائمة السوق المرخّصة واختر الأصول المتاحة للاعبين. تستخدم المراكز لقطات مسجلة، لا أسعار المتصفح.'],['title'=>'تداول الأسهم','body'=>'حدّث قائمة الأسهم وفعّل الأصول أو عطّلها. تبقى أدلة الجولات الموجودة محفوظة عند تغيير الإتاحة.'],['title'=>'الشركاء والإحالات','body'=>'اضبط نسب الإحالة وراجع البرنامج. تؤثر التغييرات في حسابات المكافآت المستقبلية.'],['title'=>'VIP واسترداد الرهان','body'=>'اضبط إعدادات VIP، وعند السماح عدّل مستوى اللاعب. تحقّق دائماً من سجل اللاعب أولاً.'],['title'=>'إعدادات النظام وAPI','body'=>'تحكم في الظهور والعلامة التجارية والموفرين والإعدادات التشغيلية. اختبر الاتصال وأبقِ طريقة تسجيل دخول واحدة على الأقل مفعلة.'],['title'=>'المتجر والترخيص','body'=>'راجع حالة الترخيص واطلب التنزيلات المدعومة ونفّذ التحديثات المعتمدة. لا تستبدل المفاتيح أو تنشر تحديثات من دون تفويض.'],['title'=>'أمان الحساب','body'=>'استخدم هذه المنطقة لكلمة مرورك وبيانات الاتصال. احمِ حساب المسؤول ولا تشارك بيانات اعتماده مطلقاً.'],
